     1	import { mkdtempSync, rmSync } from "fs";
     2	import { tmpdir } from "os";
     3	import { join } from "path";
     4	import { App, createApp } from "../src/app";
     5	import { eq, onCleanup, run, test } from "./harness";
     6	
     7	interface Report {
     8	  runId: number;
     9	  batch: number;
    10	  planned: number;
    11	  published: number;
    12	  delivered: number;
    13	  failed: number;
    14	  skippedOptOut: number;
    15	  lines: { orderNo: string; customerId: string; kind: string; status: string; to: string }[];
    16	  text: string;
    17	}
    18	
    19	interface CustomerAlerts {
    20	  customerId: string;
    21	  delivered: { orderNo: string; kind: string }[];
    22	  inbox: string[];
    23	}
    24	
    25	/** 빈 스풀 디렉토리를 가진 앱 하나 */
    26	function world() {
    27	  const spoolDir = mkdtempSync(join(tmpdir(), "alerts-"));
    28	  onCleanup(() => rmSync(spoolDir, { recursive: true, force: true }));
    29	  const app: App = createApp({ spoolDir, mqpubBin: join(process.cwd(), "vendor", "bin", "mqpub") });
    30	
    31	  const call = (method: string, url: string, body?: unknown): unknown => {
    32	    const r = app.handle(method, url, body);
    33	    eq(r.status, 200, `${method} ${url} → ${JSON.stringify(r.body)}`);
    34	    return r.body;
    35	  };
    36	
    37	  return {
    38	    app,
    39	    spoolDir,
    40	    customer(id: string, name: string, phone: string, smsOptIn = true): void {
    41	      call("POST", "/customers", { id, name, phone, smsOptIn });
    42	    },
    43	    order(customerId: string, placedOn: string, channel: "direct" | "market" = "direct", partner?: string): string {
    44	      return (call("POST", "/orders", { customerId, placedOn, channel, partner }) as { orderNo: string }).orderNo;
    45	    },
    46	    event(orderNo: string, kind: string): void {
    47	      call("POST", `/orders/${encodeURIComponent(orderNo)}/events`, { kind });
    48	    },
    49	    dispatch(): Report {
    50	      return call("POST", "/dispatch") as Report;
    51	    },
    52	    report(runId: number): Report {
    53	      return call("GET", `/reports/dispatch/${runId}`) as Report;
    54	    },
    55	    alerts(customerId: string): CustomerAlerts {
    56	      return call("GET", `/customers/${customerId}/alerts`) as CustomerAlerts;
    57	    },
    58	  };
    59	}
    60	
    61	test("every customer whose order shipped today gets a shipping text", () => {
    62	  const w = world();
    63	  const shoppers: [string, string, string][] = [
    64	    ["C1001", "김하늘", "010-2000-1001"],
    65	    ["C1002", "이도윤", "010-2000-1002"],
    66	    ["C1003", "박서연", "010-2000-1003"],
    67	    ["C1004", "최민준", "+82 10-2000-1004"],
    68	    ["C1005", "정지우", "010 2000 1005"],
    69	    ["C1006", "강예린", "010-2000-1006"],
    70	    ["C1007", "윤시우", "010-2000-1007"],
    71	  ];
    72	  for (const [id, name, phone] of shoppers) w.customer(id, name, phone);
    73	
    74	  const orders = [
    75	    w.order("C1001", "2026-10-07"),
    76	    w.order("C1002", "2026-10-07"),
    77	    w.order("C1003", "2026-10-07"),
    78	    w.order("C1004", "2026-10-08"),
    79	    w.order("C1005", "2026-10-08", "market", "GMKT"),
    80	    w.order("C1006", "2026-10-08", "market", "GMKT"),
    81	    w.order("C1007", "2026-10-08", "market", "ELVN"),
    82	  ];
    83	  for (const o of orders) w.event(o, "SHIPPED");
    84	
    85	  const report = w.dispatch();
    86	  eq(report.planned, 7, "planned alerts");
    87	  eq(report.lines.filter((l) => l.status !== "발송").map((l) => l.orderNo), [], "alerts not sent");
    88	  eq(report.delivered, 7, "sent count on the dispatch report");
    89	
    90	  for (const [id] of shoppers) {
    91	    const a = w.alerts(id);
    92	    eq(a.inbox.length, 1, `texts received by ${id}`);
    93	    eq(a.inbox[0].includes("출발"), true, `shipping wording for ${id}`);
    94	  }
    95	});
    96	
    97	test("opted-out customers are not texted and are counted separately", () => {
    98	  const w = world();
    99	  w.customer("C2001", "한지민", "010-3000-2001");
   100	  w.customer("C2002", "오세훈", "010-3000-2002", false);
   101	  w.event(w.order("C2001", "2026-10-09"), "PAID");
   102	  w.event(w.order("C2002", "2026-10-09"), "PAID");
   103	  const report = w.dispatch();
   104	  eq(report.skippedOptOut, 1, "opted out");
   105	  eq(report.delivered, 1, "sent");
   106	  eq(w.alerts("C2002").inbox, [], "no text for opted-out");
   107	});
   108	
   109	test("each dispatch run goes out as one batch and nothing is sent twice", () => {
   110	  const w = world();
   111	  w.customer("C3001", "서지호", "010-4000-3001");
   112	  const o = w.order("C3001", "2026-10-09");
