   118	  eq([r1.batch, r2.batch], [1, 2], "batch per run");
   119	  eq(r3.planned, 0, "nothing new");
   120	  eq(w.alerts("C3001").inbox.length, 2, "two texts total");
   121	  eq(w.report(1).delivered, 1, "stored report for run 1");
   122	});
