import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 논리 키 — 사내 키 규약 `<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 같은 이벤트는 늘 같은 논리 키이며, 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비).
 */
function logicalKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  return `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
}

/**
 * 와이어 키 — mqpub은 한 배치 안에서 키의 앞 16바이트가 같으면 뒤 메시지를 조용히 버린다.
 * 공통 접두(네임스페이스·이벤트명)를 가진 논리 키는 그 16바이트가 서로 같아지므로,
 * 전체 논리 키의 결정적 해시 16자를 맨 앞에 둬서 메시지마다 앞 16바이트가 달라지게 한다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = logicalKey(namespace, kind, orderNo);
  return `${createHash("sha1").update(logical).digest("hex").slice(0, 16)}:${logical}`;
}

